let peaks=[],decades=[],sortKey='height',sortDirection=-1,searchTimer;const $=s=>document.querySelector(s),fmt=n=>Number(n||0).toLocaleString(),normalize=s=>String(s??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().trim(),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function params(){return new URLSearchParams(location.search)}function assertPeakFields(rows){const required=['peakId','name','heightM','expeditions','memberAttempts','memberSummits','memberSummitRate','deaths','decadeCounts'];const missing=required.filter(field=>rows.some(row=>!Object.prototype.hasOwnProperty.call(row,field)));if(missing.length)throw Error('Peak export is missing required fields: '+missing.join(', '))}function updateUrl(){const p=new URLSearchParams({q:$('#search').value,status:$('#status').value,minimum:$('#minimum').value,sort:sortKey,direction:sortDirection<0?'desc':'asc'});history.replaceState(null,'','peaks.html?'+p)}
function comparator(a,b){if(sortKey==='name')return a.name.localeCompare(b.name)*sortDirection;if(sortKey==='trend')return (a.expeditions-b.expeditions)*sortDirection;const field=sortKey==='height'?'heightM':sortKey==='rate'?'memberSummitRate':sortKey;const av=a[field],bv=b[field];if(av==null&&bv==null)return a.name.localeCompare(b.name);if(av==null)return 1;if(bv==null)return -1;return (bv-av)*sortDirection||a.name.localeCompare(b.name)}
function sparkline(peak){const valueAt=(list,index)=>list[index]||0,values=decades.map(decade=>Number((peak.decadeCounts||{})[decade]||0)),max=Math.max(1,...values),busiest=values.reduce((best,value,index)=>value>valueAt(values,best)?index:best,0),step=111/Math.max(1,values.length-1),points=values.map((value,index)=>(2+index*step)+','+(26-value/max*22)).join(' ');if(!values.some(Boolean))return '<svg class="spark" viewBox="0 0 115 28" role="img" aria-label="'+esc(peak.name)+': no expedition history"><path d="M2 26H113" stroke="#263b40" fill="none"/></svg>';return '<svg class="spark" viewBox="0 0 115 28" role="img" aria-label="'+esc(peak.name)+': busiest decade '+decades[busiest]+' with '+fmt(values[busiest])+' expeditions"><polyline points="'+points+'" fill="none" stroke="#9de7e0" stroke-width="1.6"/><circle cx="'+(2+(values.length-1)*step)+'" cy="'+(26-values.at(-1)/max*22)+'" r="2.5" fill="#f1ba76"/></svg>'}
function filtered(){const q=normalize($('#search').value),status=$('#status').value,minimum=Number($('#minimum').value);return peaks.filter(p=>(!q||[p.name,p.alternateName,p.location,p.peakId].some(value=>normalize(value).includes(q)))&&(p.memberAttempts>=minimum)&&(status==='all'||status==='hasSummits'&&p.memberSummits>0||status==='noSummits'&&p.memberSummits===0||status==='open'&&p.open||status==='trekking'&&p.trekking)).sort(comparator)}
function render(){const rows=filtered();$('#result-note').textContent=rows.length+' peak'+(rows.length===1?'':'s')+' shown';$('#rows').innerHTML=rows.length?rows.map(p=>'<tr><td><a class="peak-name" href="peak.html?peak='+encodeURIComponent(p.peakId)+'&population=members"><span><strong>'+esc(p.name)+'</strong><small>'+esc(p.peakId)+' · '+esc(p.location||'location not recorded')+'</small></span></a></td><td>'+ (p.heightM==null?'-':fmt(p.heightM)+' m')+'</td><td>'+fmt(p.expeditions)+'</td><td>'+sparkline(p)+'</td><td class="rate">'+(p.memberSummitRate==null?'-':p.memberSummitRate.toFixed(1)+'%<small>n = '+fmt(p.memberAttempts)+'</small>')+'</td><td>'+fmt(p.deaths)+'</td></tr>').join(''):'<tr><td colspan="6" class="empty">No peaks match that search.</td></tr>';document.querySelectorAll('[data-sort]').forEach(button=>button.setAttribute('aria-sort',button.dataset.sort===sortKey?(sortDirection>0?'ascending':'descending'):'none'))}
function applyState(){const p=params();if(p.get('q')!==null)$('#search').value=p.get('q');if(['all','hasSummits','noSummits','open','trekking'].includes(p.get('status')))$('#status').value=p.get('status');if(['0','10','50','100'].includes(p.get('minimum')))$('#minimum').value=p.get('minimum');if(['name','height','expeditions','trend','rate','deaths'].includes(p.get('sort')))sortKey=p.get('sort');if(p.get('direction')==='desc')sortDirection=-1}
document.querySelectorAll('[data-sort]').forEach(button=>{const activate=()=>{if(sortKey===button.dataset.sort)sortDirection*=-1;else{sortKey=button.dataset.sort;sortDirection=sortKey==='name'?1:-1}updateUrl();render()};button.addEventListener('click',activate);button.addEventListener('keydown',event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();activate()}})});['status','minimum'].forEach(id=>$('#'+id).addEventListener('change',()=>{updateUrl();render()}));$('#search').addEventListener('input',()=>{clearTimeout(searchTimer);searchTimer=setTimeout(()=>{updateUrl();render()},150)});Promise.resolve().then(()=>fetch('peaks.json')).then(response=>{if(!response.ok)throw Error('Peak data file is missing');return response.json()}).then(rows=>{assertPeakFields(rows);peaks=rows;decades=[...new Set(peaks.flatMap(p=>Object.keys(p.decadeCounts||{}).map(Number)))].sort((a,b)=>a-b);$('#peak-count').textContent=fmt(peaks.length);applyState();render()}).catch(error=>{$('#peak-count').textContent='-';$('#result-note').textContent='Build local data first';$('#browser').hidden=true;$('#error').hidden=false;$('#error').innerHTML='<strong>'+esc(error.message)+'</strong><p>Run scripts/build_data.py, dbt build, and scripts/export_site_data.py, then reload this page.</p>'});
